def parse_env(env_string):
    env = {}
    for line in env_string.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' in line:
            key, _, value = line.partition('=')
            env[key.strip()] = value.strip()
    return env

def check_required_vars(env, required):
    return [var for var in required if var not in env]

def validate_port(port_str):
    try:
        port = int(port_str)
        if 1 <= port <= 65535:
            return [True, port]
        return [False, None]
    except (TypeError, ValueError):
        return [False, None]

def generate_report(service, env, required):
    missing = check_required_vars(env, required)
    port_ok, _ = validate_port(env.get('PORT', ''))
    ok = len(missing) == 0 and port_ok
    return {'service': service, 'missing': missing, 'port_valid': port_ok, 'ok': ok}
